package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.service.PayrollReportService;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/manager/payroll/reports") public class PayrollReportController{final PayrollReportService s;public PayrollReportController(PayrollReportService s){this.s=s;}@GetMapping("/monthly-summary") public ResponseEntity<ApiResponse<PayrollSummaryResponse>> m(@RequestParam int month,@RequestParam int year){return ResponseEntity.ok(ApiResponse.ok("Monthly summary",s.monthlySummary(month,year)));}@GetMapping("/by-role") public ResponseEntity<ApiResponse<java.util.List<PayrollReportResponse>>> r(@RequestParam int month,@RequestParam int year){return ResponseEntity.ok(ApiResponse.ok("Role report",s.byRole(month,year)));}@GetMapping("/by-department") public ResponseEntity<ApiResponse<java.util.List<PayrollReportResponse>>> d(@RequestParam int month,@RequestParam int year){return ResponseEntity.ok(ApiResponse.ok("Department report",s.byDepartment(month,year)));}@GetMapping("/payments") public ResponseEntity<ApiResponse<java.util.List<PayrollReportResponse>>> p(@RequestParam int month,@RequestParam int year){return ResponseEntity.ok(ApiResponse.ok("Payment report",s.payments(month,year)));}@GetMapping("/branch-wise-summary") public ResponseEntity<ApiResponse<java.util.List<PayrollReportResponse>>> b(){return ResponseEntity.ok(ApiResponse.ok("Branch report",s.branchWise()));}}
